SINA_SMART["bacterio1-mycobacteria"] = {"lecture":"bacterio1-mycobacteria","title":"Mycobacteria and tuberculosis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"bacterio1-mycobacteria:e0","text":"Acid-fast bacilli: lipid-rich wall resists acid-alcohol decolourisation.","topic":"The genus Mycobacterium","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e1","text":"M. tuberculosis: strictly human, airborne, strict aerobe, very slow growth.","topic":"The genus Mycobacterium","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e3","text":"Morocco: 29,018 new cases (2020); risk: malnutrition, HIV.","topic":"Epidemiology in Morocco","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e4","text":"~10 bacilli can infect; blocks phagosome acidification; granuloma → latency.","topic":"Pathogenesis and virulence","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e5","text":"Virulence lipids: PDIM, PGL.","topic":"Pathogenesis and virulence","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e2","text":"Löwenstein-Jensen: rough buff colonies in 2-6 weeks.","topic":"Laboratory diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e6","text":"Samples: 3 early-morning sputa; Ziehl-Neelsen or auramine.","topic":"Laboratory diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e7","text":"GeneXpert: PCR + rifampicin resistance.","topic":"Laboratory diagnosis","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e8","text":"Standard: 2RHZE / 4RH (6 months), DOT, control at 2 months.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"bacterio1-mycobacteria:e9","text":"MDR-TB ≥ 15 months; BCG at birth.","topic":"Treatment and prevention","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1kjjzip":"a","1pego8u":"a","qfxbux":"a","1g81qd":"a","q27vji":"a","1szxvqd":"a","e3v7m9":"a","zssakt":"a","1su3p0k":"a","1yigw3r":"a","1s4xh0g":"a","yblxgn":"a","tvmp3m":"a","twwhr8":"a","8ka03a":"x"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"bacterio1-mycobacteria:e0":{"s":0,"u":["Acid-fast bacilli: lipid-rich wall resists acid-alcohol decolourisation.","Their lipid-rich wall resists decolourisation by acid and alcohol: they are acid-fast bacilli (AFB) ."],"dp":[]},"bacterio1-mycobacteria:e1":{"s":0,"u":["M. tuberculosis: strictly human, airborne, strict aerobe, very slow growth.","M. tuberculosis : slender, slightly curved rods (0.2-0.6 × 1-10 µm), non-motile, non-sporing, catalase and nitrate reductase positive , a strictly human pathogen with airborne transmission , a strict aerobe growing very slowly on Löwenstein-Jensen medium (colonies after up to 6 weeks at 37 °C)."],"dp":[]},"bacterio1-mycobacteria:e3":{"s":1,"u":["Morocco: 29,018 new cases (2020); risk: malnutrition, HIV.","Tuberculosis remains a public health priority in Morocco: 29,018 new cases in 2020 ; between 2000 and 2023 incidence fell by about 19% and mortality by 6%.","Risk factors: malnutrition , immunodepression (the HIV-TB association), and close contact with a contagious patient (family, health professionals)."],"dp":[]},"bacterio1-mycobacteria:e4":{"s":2,"u":["~10 bacilli can infect; blocks phagosome acidification; granuloma → latency.","Alveolar macrophages ingest them, but mycobacteria block phagosome acidification and multiply inside."],"dp":[]},"bacterio1-mycobacteria:e5":{"s":2,"u":["Virulence lipids: PDIM, PGL.","Surface lipids phthiocerol dimycocerosate (PDIM) and phenolic glycolipids (PGL) are major virulence factors."],"dp":[]},"bacterio1-mycobacteria:e2":{"s":3,"u":["Löwenstein-Jensen: rough buff colonies in 2-6 weeks.","Culture : Löwenstein-Jensen, rough, dry, buff 'cauliflower' colonies in 2-6 weeks; liquid culture (MGIT) is faster."],"dp":[]},"bacterio1-mycobacteria:e6":{"s":3,"u":["Samples: 3 early-morning sputa; Ziehl-Neelsen or auramine.","Microscopy : Ziehl-Neelsen (red bacilli on blue) or auramine fluorescence (faster screening).","Samples : for lung disease, early-morning fasting sputum , bronchial or gastric aspirates, three times ; for extrapulmonary disease, urine, CSF, pleural fluid, biopsies."],"dp":[]},"bacterio1-mycobacteria:e7":{"s":3,"u":["GeneXpert: PCR + rifampicin resistance.","Current standard: PCR / NAAT such as GeneXpert , which also detects rifampicin resistance , and line probe assays."],"dp":[]},"bacterio1-mycobacteria:e8":{"s":4,"u":["Standard: 2RHZE / 4RH (6 months), DOT, control at 2 months.","Standard drug-susceptible regimen: 6 months, 2RHZE / 4RH : an intensive phase of 2 months with four drugs, then 4 months of rifampicin + isoniazid.","Extrapulmonary TB 6-9 months (up to 12 if severe); relapses need longer regimens; MDR/RR-TB ≥ 15 months with second-line drugs (amikacin, kanamycin, fluoroquinolones, cycloserine)."],"dp":[{"h":"Why TB needs six months of treatment","t":"Most bacterial infections clear in days, but M. tuberculosis divides only every 15-20 hours and part of the population sits dormant inside granulomas and caseous material, barely metabolising. Drugs that kill actively dividing bacilli (isoniazid) act fast on the multiplying population, while rifampicin and pyrazinamide are needed to reach the slow and semi-dormant ones. Stopping early leaves survivors that cause relapse, often with acquired resistance, which is why adherence and directly observed therapy are central to TB control. Source: the lecture's slow growth, latency and 2RHZE/4RH regimen."}]},"bacterio1-mycobacteria:e9":{"s":4,"u":["MDR-TB ≥ 15 months; BCG at birth.","Prevention : finding and treating patients, screening family and contacts, and BCG at birth in the national immunisation plan.","Extrapulmonary TB 6-9 months (up to 12 if severe); relapses need longer regimens; MDR/RR-TB ≥ 15 months with second-line drugs (amikacin, kanamycin, fluoroquinolones, cycloserine)."],"dp":[]}},"meta":{"1kjjzip":{"a":"recall","vg":"bacterio1-mycobacteria:e0/recall/1"},"1pego8u":{"a":"recall","vg":"bacterio1-mycobacteria:e6/recall/1"},"qfxbux":{"a":"recall","vg":"bacterio1-mycobacteria:e1/recall/1"},"1g81qd":{"a":"recall","vg":"bacterio1-mycobacteria:e2/recall/1"},"q27vji":{"a":"recall","vg":"bacterio1-mycobacteria:e2/recall/2"},"1szxvqd":{"a":"recall","vg":"bacterio1-mycobacteria:e1/recall/2"},"e3v7m9":{"a":"recall","vg":"bacterio1-mycobacteria:e4/recall/1"},"zssakt":{"a":"recall","vg":"bacterio1-mycobacteria:e5/recall/1"},"1su3p0k":{"a":"recall","vg":"bacterio1-mycobacteria:e6/recall/2"},"1yigw3r":{"a":"recall","vg":"bacterio1-mycobacteria:e7/recall/1"},"1s4xh0g":{"a":"recall","vg":"bacterio1-mycobacteria:e8/recall/1"},"yblxgn":{"a":"recall","vg":"bacterio1-mycobacteria:e8/recall/2"},"tvmp3m":{"a":"recall","vg":"bacterio1-mycobacteria:e8/recall/3"},"twwhr8":{"a":"recall","vg":"bacterio1-mycobacteria:e9/recall/1"}},"explRev":"2a42cec69db9"};
